def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de 15 son 'FizzBuzz'
    - Los demás son el número como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales.
    Devuelve la tupla (elemento, longitud). Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = lista[i - 1]
            current_racha = 1

    # Verificar la última racha
    if current_racha > max_racha:
        max_racha = current_racha
        max_element = lista[-1]

    return (max_element, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra en minuscula y las siguientes con la inicial en mayuscula,
    sin guiones bajos.
    """
    if not s:
        return s

    words = s.split()
    result = []

    for i, word in enumerate(words):
        if i == 0:
            result.append(word.lower())
        else:
            result.append(word[0].upper() + word[1:])

    return ''.join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    # Lista para almacenar los primos encontrados
    primos = []

    # Verificar si n es primo
    if n < 2:
        return []

    # Verificar si n es primo
    if n == 2:
        primos.append(n)
        return primos

    # Verificar si n es par
    if n % 2 == 0:
        return primos

    # Verificar divisibilidad por números impares desde 3 hasta sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            break

    if n % i == 0:
        return primos

    # Si llegamos aquí, n es primo
    primos.append(n)
    return primos

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    """
    Aplica codificación por repeticiones: 'aaabb' se convierte en 'a3b2'.
    Si la versión comprimida no es más corta que la original, devuelve la original.
    """
    if not s:
        return s

    # Contar frecuencias de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la versión comprimida
    compressed = ""
    for char, count in counts.items():
        compressed += char + str(count)

    # Verificar si es más corta
    if len(compressed) <= len(s):
        return compressed
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Un texto vacío está balanceado.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados, False en caso contrario.
    """
    if not s:
        return True

    open_paren = 0
    open_bracket = 0
    open_brace = 0

    for char in s:
        if char == '(':
            open_paren += 1
        elif char == '[':
            open_bracket += 1
        elif char == '{':
            open_brace += 1
        elif char == ')':
            if open_paren == 0:
                return False
            open_paren -= 1
        elif char == ']':
            if open_bracket == 0:
                return False
            open_bracket -= 1
        elif char == '}':
            if open_brace == 0:
                return False
            open_brace -= 1

    return open_paren == 0 and open_bracket == 0 and open_brace == 0

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del string están bien balanceados y anidados.
    Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados, False en caso contrario.
    """
    open_brackets = {'(', '[', '{'}
    close_brackets = {')', ']', '}'}
    stack = []

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top = stack.pop()
            if top != char:
                return False

    return len(stack) == 0

def trozos(lista, n):
    """Partir una lista en sublistas de tamaño n. La última puede ser más corta."""
    if n <= 0:
        return []
    return [lista[i:i + n] for i in range(0, len(lista), n)]

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

